/// <reference types="node" />
// W1: the web tokenizer + LiteRT.js run of shared/ai/classifier/model.tflite must give what Kotlin/Python give
// (core/ai/src/test/resources/classifier_reference.json, generated by tools/classifier/export_tflite.py).
import { test, expect, beforeAll } from 'vitest'
import fs from 'node:fs'
import vm from 'node:vm'
import path from 'node:path'
import { createRequire } from 'node:module'
import { runClassifier, makeTokenizer, decide, analysis, sentences, suggestTitle, nearest, central, MAX_LEN, type LrtModel, type TensorCtor } from '../src/emotion'
import tokenizerJson from '../../shared/ai/classifier/tokenizer.json'
import ref from '../../core/ai/src/test/resources/classifier_reference.json'

const encode = makeTokenizer(tokenizerJson as never)
type Ref = { text: string; ids: number[]; probs: number[]; predict: { key: string; intensity: number }[] }
const refs = ref as Ref[]

test('tokenizer ids match the reference', () => {
  for (const r of refs) expect(encode(r.text), r.text).toEqual(r.ids)
})

test('decision rule matches the reference', () => {
  for (const r of refs) expect(decide(r.text, r.probs).map(e => [e.key, e.intensity]), r.text).toEqual(r.predict.map(e => [e.key, e.intensity]))
})

test('long text is cut to maxLen with [CLS] … [SEP]', () => {
  const ids = encode('오늘 정말 피곤했다. '.repeat(100))
  expect(ids.length).toBe(MAX_LEN); expect(ids[0]).toBe(2); expect(ids.at(-1)).toBe(3)
})

// LiteRT.js loads its emscripten script with importScripts (browser/worker). In Node: eval it with require/__dirname.
let model: Awaited<ReturnType<typeof import('@litertjs/core').loadAndCompile>>
beforeAll(async () => {
  const require = createRequire(import.meta.url)
  const g = globalThis as Record<string, unknown>
  g.self = globalThis
  g.importScripts = (f: string) => vm.runInThisContext(`(function(require,__dirname,__filename){${fs.readFileSync(f, 'utf8')}\n;globalThis.ModuleFactory=ModuleFactory})`)(require, path.dirname(f), f)
  const lrt = await import('@litertjs/core')
  await lrt.loadLiteRt(path.dirname(require.resolve('@litertjs/core/wasm/litert_wasm_compat_internal.js')) + '/')
  model = await lrt.loadAndCompile(new Uint8Array(fs.readFileSync(new URL('../../shared/ai/classifier/model.tflite', import.meta.url))), { accelerator: 'wasm' })
}, 60000)

test('LiteRT.js model output matches the reference probabilities', async () => {
  const { Tensor } = await import('@litertjs/core')
  let worst = 0; const ms: number[] = []
  for (const r of refs) {
    const t0 = performance.now()
    const { logits } = await runClassifier(model as unknown as LrtModel, Tensor as unknown as TensorCtor, encode(r.text))
    ms.push(performance.now() - t0)
    const a = analysis(r.text, logits)
    r.probs.forEach((p, i) => { worst = Math.max(worst, Math.abs(1 / (1 + Math.exp(-logits[i])) - p)) })
    expect(a.emotions.map(e => e.key), r.text).toEqual(r.predict.map(e => e.key))
  }
  console.log(`classifier: max |p - ref| ${worst.toFixed(5)}, ${Math.round(ms.reduce((a, b) => a + b) / ms.length)} ms/text (Node wasm)`)
  expect(worst).toBeLessThan(0.02)
}, 60000)

test('sentences / title / embedding helpers', () => {
  const s = sentences('오늘 비가 왔다. 친구랑 떡볶이 먹었어!! 진짜 행복했음\n끝')
  expect(s.map(x => x.text)).toEqual(['오늘 비가 왔다.', '친구랑 떡볶이 먹었어!!', '진짜 행복했음'])
  expect(s[1].start).toBe(10)
  const a = (key: string, strength: number) => ({ emotions: [{ key, intensity: 3 }], strength })
  expect(suggestTitle([{ text: '오늘 비가 왔다.', a: a('unsure', 0) }, { text: '친구랑 떡볶이 먹어서 진짜 행복했어!', a: a('joy', .8) }], 'joy')).toBe('친구랑 떡볶이 먹어서 진짜 행복했어')
  expect([...suggestTitle([{ text: '가나다라마바사 아자차카타파하 가나다라마바사 아자차카', a: a('joy', 1) }])].length).toBeLessThanOrEqual(20)
  const items = [{ item: 'a', v: [1, 0] }, { item: 'b', v: [0.9, 0.1] }, { item: 'c', v: [0, 1] }]
  expect(nearest([1, 0], items, 2, 0.5).map(x => x.item)).toEqual(['a', 'b'])
  expect(central(items)).toBe('b')
})
